// 1200x800 PNG shown on every default service until the tenant replaces it.
// Text is baked into the pixels (not rendered from SVG at seed time) because
// SVG <text> silently drops in serverless runtimes without fonts.
// Embedded rather than read from public/ since static files aren't reliably
// present on the function filesystem in production.
export const SAMPLE_SERVICE_IMAGE_WIDTH = 1200;
export const SAMPLE_SERVICE_IMAGE_HEIGHT = 800;
export const SAMPLE_SERVICE_IMAGE_BASE64 =
  "";
